<?php require __DIR__.'/diagnostic_filters.php'; ?>
<div class="section-title"><span class="muted">共 <?= number_format($total) ?> 条事件 · 事件发生时间排序</span><a class="btn ghost sm" href="<?= e(lc_diag_url('/admin')) ?>">返回排障工作台</a></div>
<div class="card table-card"><div class="table-scroll"><table><thead><tr><th>发生时间</th><th>设备 / 软件版本</th><th>平台</th><th>事件结果</th><th>内容与来源</th><th>排查</th></tr></thead><tbody>
<?php foreach($rows as $row): ?><tr><td class="nowrap"><?= e($row['occurred_at']) ?></td><td><a class="mono" href="/admin/userdata/<?= e(rawurlencode($row['identity'])) ?>"><?= e($row['identity']) ?></a><div class="muted">v<?= e($row['version'] ?: '未上报') ?></div></td><td><?= e(lc_names()[$row['platform']] ?? ($row['platform']==='unknown'?'未识别':$row['platform'])) ?></td><td><span class="badge <?= $row['error_type']?'bad':'muted' ?>"><?= e(lc_outcome_names()[$row['outcome']] ?? $row['outcome']) ?></span><?php if($row['stage']): ?><div class="muted"><?= e($row['stage']) ?></div><?php endif; ?></td><td class="event-message"><div><?= e(mb_substr($row['message'],0,220)) ?></div><small><?= e(lc_source_name($row['source'])) ?><?php if($row['run_id']): ?> · 任务 <?= e($row['run_id']) ?><?php endif; ?></small></td><td class="ops"><?php if($row['fingerprint']): ?><a href="<?= e(lc_diag_url('/admin/issues/'.$row['fingerprint'])) ?>">问题详情</a><?php endif; ?><?php if($row['log_id']): ?><a class="btn ghost sm" href="/admin/logs/<?= (int)$row['log_id'] ?>?back=<?= e(rawurlencode($_SERVER['REQUEST_URI'])) ?>">原始日志</a><?php endif; ?></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="6" class="empty">没有符合筛选条件的事件。可扩大时间范围或按设备查看原始日志。</td></tr><?php endif; ?></tbody></table></div></div>
<nav class="pager" aria-label="事件分页"><span>第 <?= (int)$page ?> / <?= (int)$pages ?> 页</span><?php foreach(['上一页'=>$page-1,'下一页'=>$page+1] as $label=>$n): if($n<1||$n>$pages)continue;$qs=$_GET;$qs['page']=$n; ?><a href="?<?= e(http_build_query($qs)) ?>"><?= e($label) ?></a><?php endforeach; ?></nav>
